class Solution {
    public long countExcellentPairs(int[] nums,int k){
        Set<Integer> unique=new HashSet<>();
        for(int value:nums)unique.add(value);
        long[] frequency=new long[31];
        for(int value:unique)frequency[Integer.bitCount(value)]++;
        long answer=0;
        for(int i=0;i<31;i++)for(int j=0;j<31;j++)if(i+j>=k)answer+=frequency[i]*frequency[j];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countExcellentPairs(nums:IntArray,k:Int):Long{
        val unique=nums.toHashSet();
        val frequency=LongArray(31);
        for(value in unique)frequency[Integer.bitCount(value)]++;
        var answer=0L;
        for(i in 0 until 31)for(j in 0 until 31)if(i+j>=k)answer+=frequency[i]*frequency[j];
        return answer
    }
}

